from png_metadata import without_scene_filename
ROOT=Path(__file__).resolve().parents[1]; A=ROOT/'assets'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
inputs=json.loads((A/'ch02-v2-pump-inputs.json').read_text(encoding='utf-8'))
for i in inputs['render_images'].values():
 target=A/i['public_file'];original=target if target.exists() else ROOT/i['acquired']
 assert sha(original) in {i['sha256'], i.get('source_render_sha256', i['sha256'])}
 assert list(Image.open(original).size)==i['dimensions_px']
 sanitized=without_scene_filename(original.read_bytes())
 assert hashlib.sha256(sanitized).hexdigest()==i['sha256']
 if original!=target or original.read_bytes()!=sanitized:target.write_bytes(sanitized)
g=inputs['source_records']['backbone_geometry']
assert inputs['source_records']['surface_render']['material_parameters']['palette_srgb_author_A_B_G']==[[.63,.67,.70],[.13,.30,.46],[.85,.48,.12]]
