 if kind=='surface':
  svg+='''<g font-family="Arial, sans-serif" font-size="42" fill="#eaf0ef" stroke-linecap="round"><g stroke="#a1abb3" stroke-width="3" fill="none"><path d="M390 1110L1050 1105"/><circle cx="1050" cy="1105" r="8"/></g><text x="45" y="1100">α · chain A</text><g stroke="#b9cad8" stroke-width="7" fill="none"><path d="M390 320L915 345"/><circle cx="915" cy="345" r="8"/></g><g stroke="#214d75" stroke-width="3" fill="none"><path d="M390 320L915 345"/><circle cx="915" cy="345" r="8"/></g><text x="45" y="290">β · chain B</text><g stroke="#d97a1f" stroke-width="3" fill="none"><path d="M1440 630L960 630"/><circle cx="960" cy="630" r="8"/></g><text x="1450" y="610">FXYD · G</text><text x="1450" y="675">partial</text></g>'''
 svg+='</svg>'
 svg=svg.replace('<text ', '<text font-family="sans-serif" font-size="42" fill="#eaf0ef" ')
