(A/'ch02-v2-pump-architecture.html').write_text((ROOT/'figures/ch02_pump_plate_v2.template.html').read_text(encoding='utf-8'),encoding='utf-8')
record=dict(status='PROVISIONAL static architecture plate; not all-rubric or V05 acceptance',date='2026-11-09',source={'entry':'3WGU','revision':'1.4,2026-08-12','assembly':'1, author determined heterotrimer','organism':'Sus scrofa, pig kidney Na/K-ATPase','method':'X-ray diffraction2.8Angstrom','state':'Na-bound conformation precedingE1P, ADP/AlF4 phosphorylation-transition analogue; no oligomycin. Protein-only views omit deposited ligands.','coordinates':'https://files.rcsb.org/download/3WGU.cif','owning':'https://www.rcsb.org/structure/3WGU','citation':'Kanai etal2013, Crystal structure of a Na+-bound Na+,K+-ATPase preceding the E1P state, DOI10.1038/nature12578','coordinate_rights':'PDB archive dataCC0; https://www.wwpdb.org/about/usage-policies . This derivative uses deposited coordinates, not the journal figure.','orientation':'https://storage.googleapis.com/opm-assets/pdb/3wgu.pdb ; https://opm.phar.umich.edu/proteins/3wgu . Proper rigid alignment only; sourceOPM mesh/texture not distributed.'},chain_key=[{'name':'alpha','author_chain':'A','label_asym':'A','modeled':994,'sequence':1016,'missing':22,'color':'neutral gray'},{'name':'beta','author_chain':'B','label_asym':'B','modeled':303,'sequence':303,'missing':0,'color':'blue family; surface dark blue, C-alpha trace lighter blue'},{'name':'FXYD','author_chain':'G','label_asym':'C','modeled':34,'sequence':65,'missing':31,'color':'amber'}],surface='Per-chain approximate external probe-centre SAS, elementalvdW radii+1.4A probe,0.4A grid, enclosedsolventfilled. NotSES/Connolly, experimental density, native optical color or combined-assembly exposed-surface partition. Independently inflated buried chain envelopes can overlap; apparent crevices are not demonstrated pores/ion paths.',trace='1331 exact polymerCalpha positions; piecewise-linear displaytube0.20A, no interpolated missing residues. Break if nonconsecutive residue/insertion ambiguity orCAdistance>4.8A; source selected chains each internally contiguous. No guessedsecondarystructure/ribbon, fullbackbonebondmodel or literalwire.',orientation='Same exact source frame/camera. Positivez extracellular-facing, negativez cytoplasmic-facing. BackbonePNG already contains OPMcomputed z±15.1A hydrophobic-reference rectangle outlines, not actualbilayertexture/leaflets/wholemembranethickness. Sidearrow is projected+z direction, not a transportvector.',labels={'operation':'PNG placed atSVG(200,100), exactsize1600x1400. Territory anchors translated by(+200,+100), no projection change. Only surface broadchain labels, no guessedresidue/domain/site.', 'source_anchors':g['labels'],'projection_audit_max_error_px':inputs['source_records']['backbone_render']['projection_max_error_pixels']},image_integrity='Two original1600x1400 renderPNGs copied unchanged; SVG embeds originalbytes at1:1coordinates. No resampling, texture generation, anatomy edits, crop or rerender.',render='OriginalBlender5.2.1,48samples, sourcecamera/seed/materials in publicinputs record; neutral-gray alpha/amber FXYD and blue-family beta are illustrative chain colors, not visible-light atomicappearance. Beta is dark blue in the surface and intentionally lighter blue in the thin C-alpha trace; exact parameters in inputs.',print={'labelled_svg_width_mm':{'surface':153,'backbone':160},'raster_width_mm':{'surface':122.4,'backbone':128},'raster_ppi':{'surface':1600/(122.4/25.4),'backbone':1600/(128/25.4)},'svg_label_font_px':42,'effective_label_pt':{'surface':42*153/2000*72/25.4,'backbone':42*160/2000*72/25.4},'external_key_min_pt':10,'plan':'Two print pages intended: compact header plus surface153mm with9.1pt vector labels; backbone160mm with9.52pt labels on nextpage. SourceSVG/render unchanged, whitehtml/body. Actual revisedPDFpagecount/legibility pending root test. No measured physicalfigurewidth inferred from renderpixels.','repair_date':'2026-11-09'},reproduction={'scope':'Composition only: publictwoPNGs+inputsJSON+generator/template. No privateworkdata required on rebuild; first-copy fallback documents acquiredrenders. Fullcoordinate/SAS/trace render method and exactsourceinputhashes remain distinct in publicinputs, with officialacquisition URLs; noGPU rerun claimed.','python':platform.python_version(),'pillow':pillow_version,'source_input_manifest':'ch02-v2-pump-inputs.json','scripts':['figures/molecular_surface_v2.py','figures/molecular_render_v4.py','figures/molecular_backbone_v3.py','figures/ch02_pump_plate_v2.py']},limitations=['Staticarchitecture, not transportcycle/trajectory/kineticrate','22alpha and31FXYD residues absent and notinvented','Ligands/glycans/lipids/waters not shown; no bilayer','Per-chainSAS overlaps cannot establish pores or functionalinterface geometry','Amber FXYD trace partially overlaps alpha at thiscamera; surfaceprimary isclearer','No domain/site labels withoutsource-residue mapping'],pending=['Independent molecular/source labels/orientation review of finalplate','Separate V05 appearance/teaching review atnative/intendedsizes','Rootdesktop650390pan/native-fit/keyboardproof','Actual twofigurePDFsource/labellegibility andpagination','Canonicalchapterintegration/release outside scope'])
record['lineage'] = inputs['lineage']
record['companion_contrast_repair'] = {'date':'2026-11-09','only_change':'beta diffuse material sRGB(.13,.30,.46) to(.36,.63,.84); all1331positions/segments/.20A/camera/guides/lights/alpha/FXYD unchanged','new_backbone_sha256':inputs['render_images']['backbone']['sha256'],'actual_print_review':'PENDING fresh root/B PDF; no V11 acceptance inferred from render.'}
record['render_scenes'] = inputs['render_scenes']
