record['metadata_sanitization']=inputs.get('metadata_sanitization',{})
record['reproduction']['metadata_helper']={'path':'figures/png_metadata.py','sha256':sha(ROOT/'figures/png_metadata.py')}
record['matching_palette'] = {'surface':{'A':[.63,.67,.70],'B':[.13,.30,.46],'G':[.85,.48,.12]},'companion':{'A':[.63,.67,.70],'B':[.36,.63,.84],'G':[.85,.48,.12]},'guides':[.50,.55,.57],'convention':'Same chain-color families, intentionally lighter beta only in thin trace for print contrast; not identical RGB.'}
record['artifacts']={p.name:sha(p) for p in [A/'ch02-v2-pump-inputs.json']+[A/i['public_file'] for i in inputs['render_images'].values()]+[A/f'ch02-v2-pump-{k}-labelled.svg' for k in ['surface','backbone']]+[A/'ch02-v2-pump-architecture.html']}
record['artifacts'].update({f:sha(A/f) for f in ['observed-image-dialog.css','observed-image-dialog.js']})
